import{z as A,x as s,o as t,c as p,q as r,j as B,D as e,d as n,s as o,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"锡电离态","description":"","frontmatter":{"title":"锡电离态","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/tin-ionization.md","filePath":"litho/tin-ionization.md","lastUpdated":1791063341000}'),d={name:"litho/tin-ionization.md"};function h(m,a,S,D,u,f){const i=s("Mermaid");return t(),p("div",null,[a[2]||(a[2]=r('<h1 id="锡电离态" tabindex="-1">锡电离态 <a class="header-anchor" href="#锡电离态" aria-label="Permalink to &quot;锡电离态&quot;">​</a></h1><div class="epigraph"><p>13.5 nm 不是锡原子自己发光，而是多价锡离子的未分辨跃迁阵列刚好压进多层膜窗口；公开讨论把这条带钉在 Sn⁸⁺–Sn¹²⁺ 一带。</p><footer>—— 改写自 Cymer / ASML 对 LPP 锡等离子体光谱的公开叙述；原子物理背景见 Bakshi, EUV Lithography</footer></div><p><a href="/litho/droplet-generator">上一课</a>把靶做成准时、同位、同质量的液滴链。缺口是：滴进焦斑之后，主脉冲必须把锡电离到<strong>会发带内光</strong>的价态，而不是随便烧成任意等离子体。本课钉公开讨论的 Sn⁸⁺–Sn¹²⁺ 窗口。碎屑如何带着这些离子打收集镜，留给<a href="/litho/tin-debris">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/euv-lpp-tin">LPP</a> 已经写过：曝光光来自锡离子自发发射，不是 10.6 μm 激光。发生器只保证质量到达；价态不对，<a href="/litho/euv-prepulse">预脉冲</a>把靶展得再漂亮也只出带外光子和动能。多层膜的带内窗口大约 2%，中心约 13.5 nm。候选元素里锡的未分辨跃迁阵列（unresolved transition array, UTA）与这条窗对齐最好，但 UTA 只在一段电荷态上密集。</p><p>太低价：4p–4d 类跃迁还没走进 13.5 nm，CE 掉。太高价：能量跑到更高电离和离子动能，带内变稀，碎屑更猛。问题因此是等离子体温度–密度必须把电荷态分布停在公开叙述的 Sn⁸⁺–Sn¹²⁺ 一带，而不是「锡等离子体」四个字。</p><p><span class="marginnote">术语翻译：UTA（未分辨跃迁阵列）像一支合唱团——单个离子发光是一条清晰的「独唱」谱线，而等离子体里 Sn⁸⁺ 到 Sn¹²⁺ 一大群离子各有无数条相近的谱线，挤在一起连成一条宽光带，光谱仪分不出单根，看起来像连续发光。这条宽带恰好盖住多层膜约 2% 的反射窗口。</span></p><h3 id="价态是分布-不是单一离子" tabindex="-1">价态是分布，不是单一离子 <a class="header-anchor" href="#价态是分布-不是单一离子" aria-label="Permalink to &quot;价态是分布，不是单一离子&quot;">​</a></h3><p>公开光谱讨论不会宣称「光源里只有 Sn¹⁰⁺」。碰撞电离、三体复合和膨胀冷却同时进行，电荷态是一条随半径和时间变的分布。工程盯的是带内功率与碎屑谱，不是某一价的数密度峰值。把某张实验室谱线上的最强价写成量产配方，会把封闭控制表误当成可引用规格。</p><p><span class="marginnote">Cymer 并入 ASML 之后，公开材料仍把 13.5 nm 归因于多价锡的 UTA，而不是某一条可指定的原子线。后课只引用「带内来自 Sn⁸⁺–Sn¹²⁺ 一带」，不要把会议海报上的电荷态直方图抄进厂内控制。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>主脉冲把展开靶加热到数十电子伏量级，电子碰撞把中性锡逐级电离。CO₂ 的临界密度低，吸收区在相对稀薄的冕，有利于把能量留在出 UTA 的价态上，而不是耦进过密核。光谱诊断看的是带内对带外、以及若干价态示踪线；量产机并不把完整电荷态解当作实时执行器。</p><p><span class="marginnote">数字实例：1 电子伏约等于 11600 K，所以「数十电子伏」的电子温度相当于几十万开尔文——比太阳表面（约 5800 K）热上百倍。就这个温度也不能把锡剥过头：烧得太狠，锡离子价态冲过窗口，带内光反而变稀。</span></p><p><span class="marginnote">常见误区：初学者容易以为「激光一打，锡就发光」。实际上中性锡要从 0 价一路被电子碰撞逐级剥到 8+ 至 12+ 才进入发带内光的区间——每一级都要一次碰撞，电离是爬楼梯，不是按开关。楼梯爬错层（过冷或过热），发光窗口就错过。</span></p><p>控制旋钮仍是上一课已经对齐的那条链：滴质量、预脉冲展开、主脉冲能量与包络、氢缓冲。价态窗口是这些旋钮的约束，不是第四套独立硬件。改滴径或改预脉冲，等于改光学厚度和膨胀时间，电荷态分布跟着走，<a href="/litho/euv-prepulse">CE</a> 与离子动能一起漂。</p><h3 id="为什么公开讨论钉在-8-到-12" tabindex="-1">为什么公开讨论钉在 8+ 到 12+ <a class="header-anchor" href="#为什么公开讨论钉在-8-到-12" aria-label="Permalink to &quot;为什么公开讨论钉在 8+ 到 12+&quot;">​</a></h3><p>锡的 4d 壳层在这段价态上给出密集的 4p–4d 类跃迁，叠成宽度与 2% 带宽相当的 UTA。邻近更高价（公开叙述里也会提到 Sn¹³⁺、Sn¹⁴⁺）仍然贡献，但再往上带内权重下降、动能碎片上升。把课标写成 Sn⁸⁺–Sn¹²⁺，是抓住公开讨论的核心窗，不是声称窗外完全不发光。</p>',17)),(t(),B(l,null,{default:e(()=>[o(i,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20TE%5B%22%E7%94%B5%E5%AD%90%E6%B8%A9%E5%BA%A6%20Te%22%5D%20--%3E%20LADDER%5B%22%E7%94%B5%E7%A6%BB%E9%98%B6%E6%A2%AF%E8%83%BD%E7%88%AC%E5%A4%9A%E9%AB%98%22%5D%0A%20%20NE%5B%22%E7%94%B5%E5%AD%90%E5%AF%86%E5%BA%A6%20ne%22%5D%20--%3E%20COLL%5B%22%E7%A2%B0%E6%92%9E%E9%A2%91%E7%8E%87%E4%B8%8E%E5%85%89%E5%AD%A6%E5%8E%9A%E5%BA%A6%22%5D%0A%20%20LOW%5B%22%E8%BF%87%E4%BD%8E%E6%B8%A9%3A%20%E5%81%9C%E5%9C%A8%E4%BD%8E%E4%BB%B7%20%E5%8F%91%E5%B8%A6%E5%A4%96%22%5D%20--%3E%20WIN%5B%22Sn8%2B%20%E8%87%B3%20Sn12%2B%20%E5%B8%A6%E5%86%85%E6%9C%80%E4%BA%AE%22%5D%0A%20%20HIGH%5B%22%E8%BF%87%E9%AB%98%E6%B8%A9%3A%20%E5%86%B2%E4%B8%8A%2013%2B%2F14%2B%20%E5%B8%A6%E5%86%85%E5%8F%98%E7%A8%80%22%5D%20--%3E%20WIN%0A%20%20COLL%20--%3E%20OVER%5B%22%E8%BF%87%E5%AF%86%3A%20%E8%87%AA%E5%90%B8%E6%94%B6%E4%B8%8E%E5%96%B7%E6%BA%85%22%5D%0A%20%20COLL%20--%3E%20UNDER%5B%22%E8%BF%87%E7%A8%80%3A%20%E6%BF%80%E5%85%89%E7%A9%BF%E9%9D%B6%20%E5%90%B8%E6%94%B6%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20WIN%20--%3E%20CE%5B%22%E5%B8%A6%E5%86%85%E5%8A%9F%E7%8E%87%E4%B8%8E%20CE%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"UTA 是大量近邻线叠在仪器与等离子体展宽之下，看起来像一条带，而不是教科书里的单线激光。电子温度决定电离阶梯能爬多高；密度决定碰撞频率和光学厚度。过密则自吸收和流体力学喷溅；过稀则吸收长度不够，激光穿靶。Sn⁸⁺–Sn¹²⁺ 是这条平衡里带内最亮的一段。",-1)),a[5]||(a[5]=E("p",null,"同一套离子也是碎屑。高价离子在鞘层里被加速，溅射收集镜帽层；未电离或低价的微滴则几乎不受磁场偏转。优化价态等于同时优化光子与损伤：把分布往高价推，可能短期 CE 好看，镜子先死。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},[n("不要把「电离」理解成曝光光束的电离。落到掩模上的是 13.5 nm 光子；锡离子绝大多数飞向收集立体角或被氢中和，进不了 "),E("a",{href:"/litho/intermediate-focus"},"IF"),n(" 之后的投影光路。")])],-1)),(t(),B(l,null,{default:e(()=>[o(i,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20DROP%5B%22%E9%94%A1%E6%BB%B4%E5%88%B0%E4%BD%8D%22%5D%20--%3E%20PP%5B%22%E9%A2%84%E8%84%89%E5%86%B2%E5%B1%95%E5%BC%80%22%5D%0A%20%20PP%20--%3E%20MP%5B%22CO%E2%82%82%20%E4%B8%BB%E8%84%89%E5%86%B2%22%5D%0A%20%20MP%20--%3E%20ION%5B%22Sn8%2B%20%E8%87%B3%20Sn12%2B%20%E5%88%86%E5%B8%83%22%5D%0A%20%20ION%20--%3E%20UTA%5B%2213.5%20nm%20UTA%22%5D%0A%20%20ION%20--%3E%20IONDEB%5B%22%E9%AB%98%E4%BB%B7%E7%A6%BB%E5%AD%90%E7%A2%8E%E5%B1%91%22%5D%0A%20%20UTA%20--%3E%20COL%5B%22%E6%94%B6%E9%9B%86%E9%95%9C%E8%BF%9B%20IF%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写发生器流体力学，也不把磁场、氢刻蚀算进电离方程。电荷态的定量碰撞辐射模型在 Bakshi 与等离子体文献里，ASML 不公开量产的 Te、ne 控制表。后课默认：说到带内 EUV，先问等离子体是否停在 Sn⁸⁺–Sn¹²⁺ 一带，而不是问「锡打亮了没有」。</p><p>氙、锂做过 EUV 源研究，谱匹配或 CE 或碎片让它们退出量产叙事。不要在本课引入未公开的离子价配方或编造光谱仪通道。</p><p><span class="marginnote">LPP 课曾把窗写到 Sn⁸⁺–Sn¹⁴⁺。那是同一族 UTA 的宽说法；本课按公开讨论的核心段收在 8+–12+，两者不是两套物理。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>带内 13.5 nm 来自多价锡的 UTA，公开讨论钉在 Sn⁸⁺–Sn¹²⁺ 一带。</li><li>滴到位只是前提；价态窗口由温度、密度和 CO₂ 吸收区共同决定。</li><li>价态是分布；单一离子标签不能当控制规格。</li><li>同一套高价离子是收集镜溅射源，CE 与碎屑必须一起看。</li><li>出处：Cymer / ASML LPP 公开光谱叙述；Bakshi, <em>EUV Lithography</em>。</li></ul>',6))])}const P=A(d,[["render",h]]);export{C as __pageData,P as default};
